// src/config/apiConfig.js
export const apiConfig = {
    host: 'localhost',
    port: 5010,
    baseUrl: () => `http://${apiConfig.host}:${apiConfig.port}`,
    endpoints: {
      mlPredictEndpoint: () => `${apiConfig.baseUrl()}/ml_predict`,
      getModelsEndpoint: () => `${apiConfig.baseUrl()}/get_models`,
      loadDataEndpoint: () => `${apiConfig.baseUrl()}/load_data`,
      historydataEndpoint: () => `${apiConfig.baseUrl()}/runs`,
      deleteRunEndpoint: () => `${apiConfig.baseUrl()}/runs`
    }
  };

export const sanitizeAndParseResponse = (responseText) => {
  // Replace NaN with null to make it JSON-compatible
  const sanitizedText = responseText.replace(/NaN/g, 'null');
  try {
    return JSON.parse(sanitizedText);
  } catch (error) {
    console.error('Error parsing sanitized response:', error);
    return null; // Return null if parsing fails
  }
};

  