#App.vue
<template>
  <div id="app">
    <label class="dark-mode-toggle">
      <input
        type="checkbox"
        id="dark-mode-switch"
        v-model="isDarkMode"
        @change="toggleDarkMode"
      >
      <span class="slider"></span>
    </label>
    <RouterView/>
    <!--<RouterView :api-data="apiData" @clear-api-data="clearApiData" /> -->
  </div>
</template>

<script>
import { ref, provide } from 'vue';
export default {
  name: 'App',
  setup() {
    const apiData = ref(null);

    const setApiData = (data) => {
      console.log('Setting apiData in App.vue:', data);
      apiData.value = data;
    };

    const clearApiData = () => {
      console.log('Clearing apiData in App.vue');
      apiData.value = null;
    };

    // Provide the apiData and methods to child components
    provide('apiData', apiData);
    provide('setApiData', setApiData);
    provide('clearApiData', clearApiData);

    return {
      apiData,
      clearApiData,
    };
  },
  data() {
    return {
      isDarkMode: false
    }
  },
  methods: {
    toggleDarkMode() {
      console.log('Toggling dark mode to:', this.isDarkMode ? 'dark' : 'light') // Debug log
      document.documentElement.setAttribute('data-theme', this.isDarkMode ? 'dark' : 'light')
    }
  },
  mounted() {
    // Initialize theme based on localStorage or default
    const savedTheme = localStorage.getItem('theme')
    this.isDarkMode = savedTheme === 'dark'
    console.log('Initial theme:', this.isDarkMode ? 'dark' : 'light') // Debug log
    document.documentElement.setAttribute('data-theme', this.isDarkMode ? 'dark' : 'light')
  },
  watch: {
    isDarkMode(newValue) {
      console.log('Theme changed to:', newValue ? 'dark' : 'light') // Debug log
      localStorage.setItem('theme', newValue ? 'dark' : 'light')
    }
  }
}
</script>

<style>
